schema:
{
  "description": "Apri il ticket di assistenza: compila i campi e scegli il metodo per ciascuno.",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "NumeroOrdine": {
        "type": "string",
        "method": "extract",
        "description": "Nell'oggetto e nel testo."
      },
      "CodiceCliente": {
        "type": "string",
        "method": "extract",
        "description": "Nel testo."
      },
      "DataOrdine": {
        "type": "date",
        "method": "extract",
        "description": "Data citata; type \"date\" la normalizza."
      },
      "Quantita": {
        "type": "integer",
        "method": "extract",
        "description": "Numero di pezzi."
      },
      "PrezzoUnitario": {
        "type": "number",
        "method": "extract",
        "description": "Prezzo unitario citato."
      },
      "Urgente": {
        "type": "string",
        "method": "classify",
        "description": "C'è  una richiesta di risposta immediata.",
        "enum": [
          "sì",
          "no"
        ]
      }
    }
  }
}
